import React, { useMemo } from 'react';
import { Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, ComposedChart, Line, ReferenceLine } from 'recharts';

interface Props {
    points: any[] | null;
    a: number;
    b: number;
}

const IntegrationChart: React.FC<Props> = ({ points, a, b }) => {
    // 1. Защита от отсутствия данных
    if (!points || !Array.isArray(points) || points.length === 0) {
        return (
            <div className="h-[350px] w-full flex items-center justify-center bg-slate-50 border border-dashed rounded-xl">
                <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest">Нет данных для графика</p>
            </div>
        );
    }

    // 2. Оптимизация для больших интервалов (Downsampling)
    const optimizedData = useMemo(() => {
        const limit = 1000; // Максимальное число точек для отрисовки
        if (points.length <= limit) return points;

        const step = Math.ceil(points.length / limit);
        return points.filter((_, i) => i % step === 0);
    }, [points]);

    return (
        <div className="h-[350px] w-full mt-4">
            <ResponsiveContainer width="100%" height="100%">
                <ComposedChart data={optimizedData}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                    <XAxis
                        dataKey="x"
                        type="number"
                        domain={['auto', 'auto']}
                        tick={{fontSize: 10}}
                        tickFormatter={(v) => v.toFixed(1)}
                    />
                    <YAxis tick={{fontSize: 10}} />

                    <Area
                        type="monotone"
                        dataKey="y"
                        stroke="none"
                        fill="#6366f1"
                        fillOpacity={0.1}
                    />
                    {/* Сама линия функции */}
                    <Line type="monotone" dataKey="y" stroke="#4f46e5" dot={false} strokeWidth={2} />

                    {/* Линии пределов интегрирования */}
                    <ReferenceLine x={a} stroke="#f43f5e" strokeDasharray="3 3" />
                    <ReferenceLine x={b} stroke="#f43f5e" strokeDasharray="3 3" />
                </ComposedChart>
            </ResponsiveContainer>
        </div>
    );
};

export default IntegrationChart;
